import { useState, useContext, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import QRCode from "qrcode.react";
import api from "../api"; // your axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [requireOtp, setRequireOtp] = useState(false);
  const [tempToken, setTempToken] = useState(null);
  const [tempUser, setTempUser] = useState(null);
  const [totpSecret, setTotpSecret] = useState(null); // for QR code
  const [error, setError] = useState("");

  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      if (!requireOtp) {
        // Step 1: login with email + password
        const res = await api.post("/auth/login", { email, password });
        const data = res.data;

        if (data.requireTotp) {
          // Student must enter OTP
          setRequireOtp(true);
          setTempToken(data.token);
          setTempUser(data.user);

          // If backend generated a new TOTP secret, it can return it here for QR code
          if (data.totpSecret) setTotpSecret(data.totpSecret);
          return;
        }

        // Admin/Comelec: login immediately
        login({ token: data.token, user: data.user });

        if (data.user.role === "admin") navigate("/admin-dashboard");
        else if (data.user.role === "comelec") navigate("/comelec-dashboard");
        else navigate("/"); // fallback
      } else {
        // Step 2: verify OTP
        const res = await api.post("/auth/totp/verify-login", {
          token: tempToken,
          otp,
        });

        login({ token: res.data.token, user: res.data.user });
        navigate("/"); // redirect after OTP success
      }
    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Login</h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {!requireOtp && (
            <>
              <input
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
              />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
              />
            </>
          )}

          {requireOtp && (
            <>
              {totpSecret && (
                <div style={{ textAlign: "center", marginBottom: "10px" }}>
                  <p style={{ fontSize: "14px", color: "#555" }}>Scan this QR code in your authenticator app:</p>
                  <QRCode value={`otpauth://totp/MyApp:${tempUser.email}?secret=${totpSecret}&issuer=MyApp`} />
                </div>
              )}

              <p style={{ color: "#555", fontSize: "14px", textAlign: "center" }}>
                Enter the 6-digit OTP from your authenticator app
              </p>
              <input
                type="text"
                placeholder="6-digit OTP"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                required
                style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", textAlign: "center", letterSpacing: "3px" }}
              />
            </>
          )}

          <button
            type="submit"
            style={{
              padding: "12px",
              borderRadius: "5px",
              border: "none",
              backgroundColor: "#007bff",
              color: "#fff",
              fontWeight: "bold",
              cursor: "pointer",
            }}
          >
            {requireOtp ? "Verify OTP" : "Login"}
          </button>
        </form>

        {error && <p style={{ marginTop: "20px", textAlign: "center", color: "red" }}>{error}</p>}
      </div>
    </div>
  );
}
